602	            filingPort.markRejectedAfterObjection(record.id(), now, conclusion);
603	            detail = new ReviewDetail(null, filingNo, record.versionNo(), "OBJECTION",
604	                    "OBJECTION_UPHELD", false,
605	                    "异议成立，备案终态驳回：" + conclusion, now);
606	        } else {
607	            filingPort.reopenPublic(record.id());
608	            detail = new ReviewDetail(null, filingNo, record.versionNo(), "OBJECTION",
609	                    "OBJECTION_NOT_UPHELD", true,
610	                    "异议不成立，恢复公示；公示期满仍按原起算日 "
611	                            + record.publicNoticeDateUtc() + "（UTC）计算，期满时刻 "
612	                            + record.publicExpiresAtUtc() + "（UTC）：" + conclusion, now);
613	        }
614	        filingPort.saveReviews(List.of(detail));
615	        updated = filingPort.findById(record.id()).orElseThrow();
616	        return buildResult(updated, List.of(detail), false, now);
617	    }
