621	    @Override
622	    @Transactional
623	    public FilingResultResponse withdraw(String filingNo, String requestId, String reason) {
624	        Instant now = now();
625	        Map<String, Object> fpFields = new LinkedHashMap<>();
626	        fpFields.put("requestId", requestId);
627	        fpFields.put("filingNo", filingNo);
628	        fpFields.put("reason", reason);
629	        String fingerprint = FingerprintSupport.sha256(fpFields);
630	
631	        Optional<FilingResultResponse> replay = resolveIdempotency(requestId, OP_WITHDRAW, fingerprint);
632	        if (replay.isPresent()) {
633	            return replay.get();
634	        }
635	
636	        FilingRecord record = filingPort.findLatestByNo(filingNo)
637	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo));
638	
639	        // 注销为终态：重复注销返回幂等成功
640	        if (record.status() == FilingStatus.WITHDRAWN) {
641	            FilingResultResponse response = buildResult(record,
642	                    filingPort.findReviews(filingNo, record.versionNo()), true, now);
643	            idempotencyPort.complete(requestId, 200, FilingStatus.WITHDRAWN.name(), filingNo,
644	                    JsonSupport.toJson(response), now);
645	            return response;
646	        }
647	        if (record.status() != FilingStatus.EFFECTIVE) {
648	            throw new ConflictException("NOT_EFFECTIVE",
649	                    "仅生效备案可注销，当前状态: " + record.status());
650	        }
651	
652	        filingPort.markWithdrawn(record.id(), now, reason);
653	        filingPort.releaseSlot(record.productCode());
654	        ReviewDetail detail = new ReviewDetail(null, filingNo, record.versionNo(), "FORM",
655	                "WITHDRAWN_TERMINAL", true,
656	                "备案注销终态，注销时刻(UTC)=" + now + "，原因=" + reason
657	                        + "；注销后该产品新宣称审查一律拒绝", now);
658	        filingPort.saveReviews(List.of(detail));
659	
660	        FilingRecord updated = filingPort.findById(record.id()).orElseThrow();
661	        FilingResultResponse response = buildResult(updated, List.of(detail), false, now);
662	        idempotencyPort.complete(requestId, 200, FilingStatus.WITHDRAWN.name(), filingNo,
663	                JsonSupport.toJson(response), now);
664	        return response;
665	    }
