777	    /**
778	     * 并发重放时等待首个事务回填响应；带超时，避免首个事务异常时无限等待。
779	     */
780	    private IdempotencyRow awaitFirstCompletion(String requestId) {
781	        long deadline = System.nanoTime() + IDEMPOTENCY_WAIT_NANOS;
782	        IdempotencyRow row;
783	        do {
784	            try {
785	                Thread.sleep(IDEMPOTENCY_WAIT_STEP_MS);
786	            } catch (InterruptedException e) {
787	                Thread.currentThread().interrupt();
788	                throw new ConflictException("IDEMPOTENCY_WAIT_INTERRUPTED",
789	                        "等待首次处理结果时被中断: " + requestId);
790	            }
791	            row = idempotencyPort.find(requestId).orElseThrow(() ->
792	                    new ConflictException("IDEMPOTENCY_RECORD_VANISHED", "幂等记录消失: " + requestId));
793	        } while ((row.httpStatus() == 0 || row.responseJson() == null || row.responseJson().isEmpty())
794	                && System.nanoTime() < deadline);
795	
796	        if (row.httpStatus() == 0 || row.responseJson() == null || row.responseJson().isEmpty()) {
797	            throw new ConflictException("IDEMPOTENCY_FIRST_RESULT_TIMEOUT",
798	                    "等待首次处理结果超时: " + requestId);
799	        }
800	        return row;
801	    }
