1	package com.example.starter.cosmetic.support;
2	
3	import com.fasterxml.jackson.databind.ObjectMapper;
4	
5	import java.nio.charset.StandardCharsets;
6	import java.security.MessageDigest;
7	import java.util.ArrayList;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.TreeMap;
11	
12	/**
13	 * 幂等指纹：覆盖 requestId 与全部业务字段。
14	 *
15	 * <p>规范化规则：Map 键按字典序排序（深层递归）；List 保持输入顺序，
16	 * 列表顺序本身亦属指纹内容。最终取规范化 JSON 的 SHA-256 十六进制摘要。</p>
17	 */
18	public final class FingerprintSupport {
19	
20	    private static final ObjectMapper MAPPER = new ObjectMapper().findAndRegisterModules();
21	
22	    private FingerprintSupport() {
23	    }
24	
25	    /** 计算业务字段指纹。 */
26	    public static String sha256(Map<String, Object> fields) {
27	        try {
28	            String canonical = MAPPER.writeValueAsString(sortDeep(fields));
29	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
30	            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
31	            StringBuilder hex = new StringBuilder(hash.length * 2);
32	            for (byte b : hash) {
33	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
34	                hex.append(Character.forDigit(b & 0xF, 16));
35	            }
36	            return hex.toString();
37	        } catch (Exception e) {
38	            throw new IllegalStateException("指纹计算失败", e);
39	        }
40	    }
41	
42	    @SuppressWarnings("unchecked")
43	    private static Object sortDeep(Object value) {
44	        if (value instanceof Map<?, ?> map) {
45	            TreeMap<String, Object> sorted = new TreeMap<>();
46	            map.forEach((k, v) -> sorted.put(String.valueOf(k), sortDeep(v)));
47	            return sorted;
48	        }
49	        if (value instanceof List<?> list) {
50	            List<Object> out = new ArrayList<>(list.size());
51	            list.forEach(item -> out.add(sortDeep(item)));
52	            return out;
53	        }
54	        return value;
55	    }
56	}
