package com.example.starter.cosmetic.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.util.Map;

/**
 * 包装标签印次登记请求。
 *
 * <p>印次绑定服务端当前已生效备案的具体修订；儿童印次必须携带各年龄档
 * 独立标识摘要（bandDigests），逐档与备案受理冻结的标识文本一致。</p>
 *
 * @param requestId    幂等键；指纹覆盖 requestId、完整参数与分档集合
 * @param printRunNo   印次号，全局唯一
 * @param productCode  产品编码（须存在已生效备案）
 * @param labelDigest  标签文本摘要（与备案一致；儿童为全局摘要，不能代替分档摘要）
 * @param bandDigests  儿童印次各年龄档独立标识摘要（bandCode -&gt; digest）；成人印次不得携带
 * @param printedCount 印刷总张数（正整数）
 */
public record RegisterPrintRunRequest(
        @NotBlank String requestId,
        @NotBlank String printRunNo,
        @NotBlank String productCode,
        @NotBlank String labelDigest,
        Map<String, String> bandDigests,
        @NotNull @Positive Integer printedCount) {
}

package com.example.starter.cosmetic.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 标签领用请求。
 *
 * @param requestId       幂等键；指纹覆盖 requestId 与全部业务字段
 * @param batchNo         合成包装批号；首次领用登记所属产品，跨产品借用拒绝
 * @param quantity        领用张数（正整数，不得超未领余额，恰领完允许）
 * @param expectedVersion 期望的印次台账版本号（乐观并发控制，不一致 409）
 */
public record IssueLabelsRequest(
        @NotBlank String requestId,
        @NotBlank String batchNo,
        @NotNull @Positive Integer quantity,
        @NotNull Integer expectedVersion) {
}

package com.example.starter.cosmetic.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 未领标签销毁登记请求。
 *
 * @param requestId       幂等键；指纹覆盖 requestId 与全部业务字段
 * @param quantity        销毁张数（正整数，仅未领部分可销毁）
 * @param expectedVersion 期望的印次台账版本号（乐观并发控制，不一致 409）
 * @param reason          销毁原因（留证）
 */
public record DestroyLabelsRequest(
        @NotBlank String requestId,
        @NotNull @Positive Integer quantity,
        @NotNull Integer expectedVersion,
        String reason) {
}

package com.example.starter.cosmetic.web.dto;

import com.example.starter.cosmetic.domain.LabelPrintRun;

import java.time.Instant;
import java.util.Map;

/**
 * 包装标签印次台账响应。时间均为 UTC。
 *
 * <p>张数守恒可核对：printedCount = issuedCount + destroyedCount + remainingCount；
 * disabledRemainingCount 单独区分禁用剩余（ACTIVE 时为 0）。</p>
 */
public record PrintRunResponse(
        String printRunNo,
        String productCode,
        String filingNo,
        int filingVersionNo,
        String filingCategory,
        String labelDigest,
        Map<String, String> bandDigests,
        int printedCount,
        int issuedCount,
        int destroyedCount,
        int remainingCount,
        int disabledRemainingCount,
        String status,
        int versionNo,
        String disabledReason,
        Instant disabledAtUtc,
        Instant createdAtUtc,
        Instant updatedAtUtc) {

    /** 由领域记录构造响应。 */
    public static PrintRunResponse from(LabelPrintRun r) {
        return new PrintRunResponse(
                r.printRunNo(), r.productCode(), r.filingNo(), r.filingVersionNo(),
                r.filingCategory().name(), r.labelDigest(), r.bandDigests(),
                r.printedCount(), r.issuedCount(), r.destroyedCount(),
                r.remainingCount(), r.disabledRemainingCount(),
                r.status().name(), r.versionNo(),
                r.disabledReason(), r.disabledAtUtc(), r.createdAtUtc(), r.updatedAtUtc());
    }
}

package com.example.starter.cosmetic.web.dto;

import com.example.starter.cosmetic.domain.LabelIssue;

import java.time.Instant;

/**
 * 标签领用凭据响应。时间均为 UTC。
 *
 * <p>备案换版/注销后已领凭据仅追加风险关联（riskFlag/riskNote/riskAtUtc），不抹历史。</p>
 */
public record LabelIssueResponse(
        Long issueId,
        String printRunNo,
        String batchNo,
        String productCode,
        int quantity,
        Instant issuedAtUtc,
        boolean riskFlag,
        String riskNote,
        Instant riskAtUtc) {

    /** 由领域记录构造响应。 */
    public static LabelIssueResponse from(LabelIssue i) {
        return new LabelIssueResponse(i.id(), i.printRunNo(), i.batchNo(), i.productCode(),
                i.quantity(), i.issuedAtUtc(), i.riskFlag(), i.riskNote(), i.riskAtUtc());
    }
}

package com.example.starter.cosmetic.web.dto;

import com.example.starter.cosmetic.domain.LabelDestruction;

import java.time.Instant;

/**
 * 未领标签销毁登记响应。时间均为 UTC。
 */
public record LabelDestructionResponse(
        Long destructionId,
        String printRunNo,
        int quantity,
        String reason,
        Instant destroyedAtUtc) {

    /** 由领域记录构造响应。 */
    public static LabelDestructionResponse from(LabelDestruction d) {
        return new LabelDestructionResponse(d.id(), d.printRunNo(), d.quantity(),
                d.reason(), d.destroyedAtUtc());
    }
}

