                    try {
                        start.await();
                        labelPrintService.issue(runNo, new IssueLabelsRequest(
                                "REQ-LCR-I-" + roundNo, "BATCH-LCR-" + roundNo, 60, 1));
                        issued.incrementAndGet();
                    } catch (ConflictException | UnprocessableException e) {
