                    assertThatThrownBy(() -> labelPrintService.issue(runNo,
                            new IssueLabelsRequest("REQ-LCD-I2-" + roundNo,
                                    "BATCH-LCD-" + roundNo, 60, run.versionNo())))
                            .isInstanceOf(UnprocessableException.class)
                            .hasMessageContaining("未领余额不足");
                }
            }
        } finally {
            pool.shutdownNow();
        }
    }
