    @Autowired
    private LabelPrintService labelPrintService;

    /**
     * 两个线程各领 60 张（印次共 100 张）：恰好一个成功，余额不为负；
     * 输家用新版本号重试仍因余额不足 422。
     */
    @Test
    void concurrentIssuesNeverExceedBalance() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
